import { Fragment } from 'react';
import { cx } from '@/lib/cx';
import './kbd.css';

/**
 * B32 · Kbd — a key, printed. Documentation of a shortcut that exists;
 * never a button, never the only way to reach an action (C4).
 */
export interface KbdProps {
  /** One key per string: ['⌘', 'K']. Rendered as separate caps. */
  keys: string[];
  /** Shown between caps for a sequence ("then"); omit for a chord. */
  separator?: string;
  className?: string;
}

export function Kbd({ keys, separator, className }: KbdProps) {
  return (
    <span className={cx('sv-kbd', className)}>
      {keys.map((key, i) => (
        <Fragment key={key}>
          {i > 0 && separator && <span className="sv-kbd__sep">{separator}</span>}
          <kbd className="sv-kbd__cap sv-mono">{key}</kbd>
        </Fragment>
      ))}
    </span>
  );
}

/* B32 · Kbd — a printed key cap. 3px radius is registered (bars/caps). */

@layer sv-components {
  .sv-kbd {
    display: inline-flex;
    align-items: center;
    gap: var(--sv-s1);
  }

  .sv-kbd__cap {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    padding: 1px 5px;
    border: 1px solid var(--sv-line);
    border-bottom-width: 2px;
    border-radius: 3px;
    background: var(--sv-wall);
    font-size: 10.5px;
    color: var(--sv-ink-soft);
  }

  .sv-kbd__sep {
    font-size: 10.5px;
    color: var(--sv-ink-faint);
  }

  .sv-band .sv-kbd__cap {
    border-color: var(--sv-band-line);
    background: transparent;
    color: var(--sv-band-soft);
  }
}
